/**
 * Checks the installed provider CLIs against what Blitz was built for.
 *
 * Provider runtimes update on their own schedule, and a change usually shows
 * up later as a failed chat or a missing model. This script reports drift
 * directly, using the requirements in `lib/server/providers/runtime-compat.ts`:
 *
 * - each CLI's version against Blitz's minimum;
 * - the Codex app-server protocol, generated by the installed CLI, against
 *   every method and enum value Blitz uses;
 * - the live Codex model catalog against Blitz's fallback model list, when
 *   Codex is signed in.
 *
 * No model turn is started and nothing is written outside a temporary
 * directory. Exits with status 1 when any check finds drift.
 *
 * Usage: npm run check:runtimes -- [--ci]
 *   --ci  Treat a missing CLI as a failure. Used by the weekly workflow,
 *         which installs the latest published CLIs without signing in.
 */

import { execFile } from "node:child_process"
import { mkdtemp, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { promisify } from "node:util"

import {
  CODEX_MODEL_OPTIONS,
  type AiProviderId,
} from "../lib/ai-model-settings.ts"
import { listCodexModels } from "../lib/server/providers/codex-models.ts"
import { providerCommand } from "../lib/server/providers/registry.ts"
import {
  CODEX_PROTOCOL_CONTRACT,
  PROVIDER_VERSION_REQUIREMENTS,
  checkProviderVersion,
  codexProtocolProblems,
  diffModelCatalog,
  hasModelCatalogDrift,
  readCodexProtocolSurface,
} from "../lib/server/providers/runtime-compat.ts"

const run = promisify(execFile)

/** Upper bound for each CLI call so a hung runtime cannot stall the check. */
const COMMAND_TIMEOUT_MS = 30_000

/** Providers with a CLI that reports its version. Antigravity's ACP server does not. */
const VERSIONED_PROVIDERS: readonly { id: AiProviderId; name: string }[] = [
  { id: "codex", name: "Codex" },
  { id: "claude-code", name: "Claude Code" },
  { id: "opencode", name: "OpenCode" },
]

/** Whether this run is the unattended weekly check. */
const ciMode = process.argv.includes("--ci")

/** Accumulates report lines and whether any of them is a failure. */
const report = { lines: [] as string[], failed: false }

/** Adds one report line, marking the run failed when `problem` is true. */
function note(line: string, problem = false): void {
  report.lines.push(line)
  if (problem) report.failed = true
}

/**
 * Runs a CLI without a shell and returns its combined output.
 *
 * @returns Output and exit status; a missing executable is reported as
 *   `missing` instead of throwing.
 */
async function runCommand(
  executable: string,
  args: readonly string[]
): Promise<{ ok: boolean; missing: boolean; output: string }> {
  try {
    const { stdout, stderr } = await run(executable, args, {
      timeout: COMMAND_TIMEOUT_MS,
    })
    return { ok: true, missing: false, output: `${stdout}${stderr}` }
  } catch (error) {
    const failure = error as NodeJS.ErrnoException & {
      stdout?: string
      stderr?: string
    }
    return {
      ok: false,
      missing: failure.code === "ENOENT",
      output: `${failure.stdout ?? ""}${failure.stderr ?? ""}`,
    }
  }
}

/** Checks one CLI's version and returns whether later checks can use it. */
async function checkVersion(provider: {
  id: AiProviderId
  name: string
}): Promise<boolean> {
  const { executable } = providerCommand(provider.id)
  const result = await runCommand(executable, ["--version"])
  if (result.missing) {
    note(`${provider.name}: not installed`, ciMode)
    return false
  }
  if (!result.ok) {
    note(`${provider.name}: \`${executable} --version\` failed`, true)
    return false
  }
  const check = checkProviderVersion(provider.id, result.output)
  const requirement = PROVIDER_VERSION_REQUIREMENTS[provider.id]
  const needs = requirement
    ? ` (needs ${requirement.minimum}+${requirement.sameMajor ? ` within v${requirement.minimum.split(".")[0]}` : ""})`
    : ""
  note(
    `${provider.name} ${check.version ?? "(unknown version)"}: ${
      check.supported ? "supported" : "UNSUPPORTED"
    }${needs}`,
    !check.supported
  )
  return check.supported
}

/** Generates the installed Codex protocol schema and checks Blitz's contract. */
async function checkCodexProtocol(
  executable: string,
  directory: string
): Promise<void> {
  const schemaDirectory = join(directory, "schema")
  const result = await runCommand(executable, [
    "app-server",
    "generate-json-schema",
    "--out",
    schemaDirectory,
  ])
  if (!result.ok) {
    note("  Protocol: could not generate the app-server schema", true)
    return
  }
  const problems = codexProtocolProblems(
    await readCodexProtocolSurface(schemaDirectory)
  )
  const methodCount =
    CODEX_PROTOCOL_CONTRACT.clientRequests.length +
    CODEX_PROTOCOL_CONTRACT.clientNotifications.length +
    CODEX_PROTOCOL_CONTRACT.serverNotifications.length +
    CODEX_PROTOCOL_CONTRACT.serverRequests.length
  if (!problems.length) {
    note(
      `  Protocol: all ${methodCount} methods and ${
        Object.keys(CODEX_PROTOCOL_CONTRACT.enums).length
      } enums Blitz uses are present`
    )
    return
  }
  note("  Protocol: DRIFT", true)
  for (const problem of problems) note(`    - ${problem}`, true)
}

/** Compares the signed-in Codex model catalog with Blitz's fallback list. */
async function checkCodexModels(
  executable: string,
  directory: string
): Promise<void> {
  const status = await runCommand(executable, ["login", "status"])
  if (!status.ok || !/logged in/i.test(status.output)) {
    note("  Models: skipped, Codex is not signed in")
    return
  }
  let live
  try {
    live = await listCodexModels({
      workspaceDirectory: directory,
      executable,
      requestTimeoutMs: COMMAND_TIMEOUT_MS,
    })
  } catch (error) {
    note(
      `  Models: could not read the catalog (${error instanceof Error ? error.message : "unknown error"})`,
      true
    )
    return
  }
  const drift = diffModelCatalog(CODEX_MODEL_OPTIONS, live)
  if (!hasModelCatalogDrift(drift)) {
    note(`  Models: fallback list matches the live catalog (${live.length})`)
    return
  }
  note(
    "  Models: DRIFT, update CODEX_MODEL_OPTIONS in lib/ai-model-settings.ts",
    true
  )
  for (const id of drift.added) note(`    + ${id} (live only)`, true)
  for (const id of drift.removed) note(`    - ${id} (no longer served)`, true)
  for (const change of drift.changed)
    note(
      `    ~ ${change.id}: fallback [${change.fallback.join(", ")}], live [${change.live.join(", ")}]`,
      true
    )
}

/** Runs every check and prints a report. */
async function main(): Promise<void> {
  const directory = await mkdtemp(join(tmpdir(), "blitz-runtime-check-"))
  try {
    for (const provider of VERSIONED_PROVIDERS) {
      const usable = await checkVersion(provider)
      if (provider.id !== "codex" || !usable) continue
      const { executable } = providerCommand("codex")
      await checkCodexProtocol(executable, directory)
      await checkCodexModels(executable, directory)
    }
    note("Antigravity: not checked, its ACP server does not report a version")
  } finally {
    await rm(directory, { recursive: true, force: true })
  }
  console.log(report.lines.join("\n"))
  console.log(
    report.failed
      ? "\nProvider runtimes have drifted from what Blitz supports."
      : "\nProvider runtimes match what Blitz supports."
  )
  process.exitCode = report.failed ? 1 : 0
}

await main()
